func (r *SessionPolicyResourceModel) ToSharedSessionPolicyServiceUpdateRequest(ctx context.Context) (*shared.SessionPolicyServiceUpdateRequest, diag.Diagnostics) {
	var diags diag.Diagnostics

	sessionPolicy, sessionPolicyDiags := r.ToSharedSessionPolicyInput(ctx)
	diags.Append(sessionPolicyDiags...)

	if diags.HasError() {
		return nil, diags
	}

	out := shared.SessionPolicyServiceUpdateRequest{
		SessionPolicy: sessionPolicy,
	}

	return &out, diags
}
